edit('src/sim/typed72_app/session.cpp','        const auto view=ai_control_view(owner);','        auto& m=*match_;bool donated=false;\n        if((m.battle.mode==MatchMode::coop||m.battle.mode==MatchMode::duo)&&!m.room.result&&m.world.players[i]&&m.world.players[i]->hp>0.){\n            const auto mates=teammates(m.battle.mode,owner);\n            if(!mates.empty()){const auto mate=mates.front(),mi=seat_index(mate);\n                if(m.world.players[mi]&&m.world.players[mi]->hp>0.&&std::find(m.tick_state.present.begin(),m.tick_state.present.end(),mate)!=m.tick_state.present.end()){\n                    const double mine=m.resources.accounts[i].balance,theirs=m.resources.accounts[mi].balance;\n                    const int amount=int(std::min(100.,std::floor((mine-theirs)*.5)));\n                    if(mine>theirs&&mine*5.+1e-9>=theirs*6.&&amount>0&&m.world.time>=m.room.players[i].gift_ready_at)\n                        donated=send("gift",{{"amount",int64_t(amount)}}).empty();\n                }\n            }\n        }\n        const auto view=ai_control_view(owner);')
